nodes = {6,10,17,37,57,72,80,87,106,111,114,116}
window = (43373, 55373)
from collections import defaultdict

# index events by unordered pair (x,y), but keep direction times
events_in_window = [e for e in events if window[0] <= e[2] <= window[1]]
# list of events where one endpoint is in nodes and the other is any
by_pair = defaultdict(list)
for u,v,t in events_in_window:
    a,b = u,v
    by_pair[(u,v)].append(t)

# For supports: find triples (x,b,t1) and (x,c,t2) where b and c in nodes and b!=c, x any node (could be in nodes)
supports_by_x = defaultdict(list)
for u,v,t in events_in_window:
    # event between u and v
    if u in nodes and v in nodes:
        # both in nodes: counts as contact between x and node? We'll treat both directions by adding entries for both endpoints
        supports_by_x[u].append((v,t))
        supports_by_x[v].append((u,t))
    elif u in nodes and v not in nodes:
        # contact between node u and outside v; x = v interacts with u
        supports_by_x[v].append((u,t))
    elif v in nodes and u not in nodes:
        supports_by_x[u].append((v,t))

closures = []
for x, lst in supports_by_x.items():
    # consider pairs of distinct nodes among lst
    from itertools import combinations
    # compress multiple interactions with same node: keep all times
    for (b,t1),(c,t2) in combinations(lst,2):
        if b==c: continue
        t_late = max(t1,t2)
        # look for closing between b and c in window with time in [t_late, t_late+800]
        # check both directions
        closers = []
        for (u,v), times in by_pair.items():
            if (u==b and v==c) or (u==c and v==b):
                for t_closing in times:
                    if t_late <= t_closing <= t_late+800:
                        closers.append((u,v,t_closing))
        if closers:
            for u,v,t_closing in closers:
                closures.append({'x':x,'b':b,'c':c,'t1':t1,'t2':t2,'t_late':t_late,'closing':(u,v,t_closing)})

print('Found closures count:', len(closures))
for c in closures[:20]:
    print(c)

# Print supports where x is in nodes (i.e., common contact is one of the target nodes)

print('\nSupports by x where x in nodes:')
for x in supports_by_x:
    if x in nodes:
        print(x, supports_by_x[x])

# Also list supports where both supports exist but no closing
no_closing = []
for x,lst in supports_by_x.items():
    from itertools import combinations
    for (b,t1),(c,t2) in combinations(lst,2):
        if b==c: continue
        t_late = max(t1,t2)
        # check if any closing exists in window at any time
        found = False
        for (u,v), times in by_pair.items():
            if (u==b and v==c) or (u==c and v==b):
                for t_closing in times:
                    if window[0] <= t_closing <= window[1]:
                        found = True
        if not found:
            no_closing.append({'x':x,'b':b,'c':c,'t1':t1,'t2':t2,'t_late':t_late})
print('\nSupport pairs without any closing in window:', len(no_closing))

